// JavaScript cell: runs right in your browser.
// nb.set() shares a value with every other cell; `return` shows a result below.
const cities = [
  { name: 'Reykjavík', lat: 64.1 },
  { name: 'London', lat: 51.5 },
  { name: 'Cairo', lat: 30.0 },
  { name: 'Singapore', lat: 1.35 },
  { name: 'Cape Town', lat: -33.9 },
];

const rad = deg => deg * Math.PI / 180;
function dayLength(lat, day) {
  const tilt = 23.44 * Math.sin(rad(360 / 365 * (day - 81)));   // sun's declination
  const x = -Math.tan(rad(lat)) * Math.tan(rad(tilt));
  return 24 / Math.PI * Math.acos(Math.max(-1, Math.min(1, x)));
}

const daylight = {};
for (const city of cities) {
  daylight[city.name] = Array.from({ length: 365 }, (_, i) => +dayLength(city.lat, i + 1).toFixed(2));
}
nb.set('cities', cities);
nb.set('daylight', daylight);
console.log(`Stored 365 days of daylight for ${cities.length} cities in nb`);

// 21 June is day 172 and 21 December is day 355.
return Object.fromEntries(cities.map(c =>
  [c.name, `${daylight[c.name][171]} h in June, ${daylight[c.name][354]} h in December`]));

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Hours of daylight through the year",
    "subtitle": "Click a city in the legend to pick it out. Southern cities peak in December."
  },
  "width": 620,
  "height": 260,
  "data": {
    "values": [
      {
        "city": "Reykjavík",
        "lat": 64.1
      },
      {
        "city": "London",
        "lat": 51.5
      },
      {
        "city": "Cairo",
        "lat": 30
      },
      {
        "city": "Singapore",
        "lat": 1.35
      },
      {
        "city": "Cape Town",
        "lat": -33.9
      }
    ]
  },
  "transform": [
    {
      "calculate": "sequence(1, 366, 2)",
      "as": "day"
    },
    {
      "flatten": [
        "day"
      ]
    },
    {
      "calculate": "23.44 * sin(2 * PI * (datum.day - 81) / 365)",
      "as": "tilt"
    },
    {
      "calculate": "24 / PI * acos(clamp(-tan(datum.lat * PI / 180) * tan(datum.tilt * PI / 180), -1, 1))",
      "as": "hours"
    },
    {
      "calculate": "datetime(2026, 0, datum.day)",
      "as": "date"
    }
  ],
  "params": [
    {
      "name": "pick",
      "select": {
        "type": "point",
        "fields": [
          "city"
        ]
      },
      "bind": "legend"
    }
  ],
  "mark": {
    "type": "line",
    "strokeWidth": 3,
    "interpolate": "monotone"
  },
  "encoding": {
    "x": {
      "field": "date",
      "type": "temporal",
      "axis": {
        "format": "%b",
        "title": null,
        "tickCount": 12
      }
    },
    "y": {
      "field": "hours",
      "type": "quantitative",
      "scale": {
        "domain": [
          0,
          24
        ]
      },
      "axis": {
        "values": [
          0,
          6,
          12,
          18,
          24
        ],
        "title": "Hours of daylight"
      }
    },
    "color": {
      "field": "city",
      "type": "nominal",
      "sort": null,
      "title": null,
      "scale": {
        "range": [
          "#6366f1",
          "#0ea5e9",
          "#f59e0b",
          "#10b981",
          "#ef4444"
        ]
      }
    },
    "opacity": {
      "condition": {
        "param": "pick",
        "value": 1
      },
      "value": 0.15
    },
    "tooltip": [
      {
        "field": "city",
        "title": "City"
      },
      {
        "field": "date",
        "type": "temporal",
        "format": "%d %b",
        "title": "Date"
      },
      {
        "field": "hours",
        "type": "quantitative",
        "format": ".1f",
        "title": "Hours"
      }
    ]
  }
}
